  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES object has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('RATES are immutable', () => {
  const original = RATES.EUR;
  RATES.EUR = 2;
  assert.equal(RATES.EUR, original);
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.deepEqual(result, { ok: true, value: 100 });
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  const expected = roundCents(10000 * 0.8425);
  assert.equal(result.value, expected);
});

test('convert with invalid currency', () => {
  const result = convert(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert case-sensitive currency', () => {
  const result = convert(100, 'usd');
  assert.equal(result.ok, false);
});

test('convert zero amount', () => {
  const result = convert(0, 'USD');
  assert.deepEqual(result, { ok: true, value: 0 });
});

test('convert negative amount', () => {
  const result = convert(-1000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value < 0, true);
});

test('convert large amount', () => {
  const result = convert(123456789, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 133950296);
});

test('convert rounds using roundCents', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(Number.isInteger(result.value), true);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney with single cent', () => {
  assert.equal(formatMoney(1, 'USD'), '$0.01');
});

test('formatMoney with no thousands', () => {
  assert.equal(formatMoney(999, 'USD'), '$9.99');
});

test('formatMoney with thousands', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
});

test('formatMoney with millions', () => {
  assert.equal(formatMoney(123456789, 'USD'), '$1,234,567.89');
});

test('formatMoney negative amount', () => {
  assert.equal(formatMoney(-123456, 'USD'), '-$1,234.56');
  assert.equal(formatMoney(-100, 'EUR'), '-€1.00');
  assert.equal(formatMoney(-5000, 'GBP'), '-£50.00');
});

test('formatMoney unknown currency', () => {
  const result = formatMoney(123456, 'JPY');
  assert.equal(typeof result, 'string');
  assert.equal(result.includes('.'), true);
});

test('formatMoney two decimal places always', () => {
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(1, 'USD'), '$0.01');
  assert.equal(formatMoney(12, 'USD'), '$0.12');
});

test('convert and format roundtrip', () => {
  const eur = 10000;
  const converted = convert(eur, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  assert.equal(formatted.includes('$'), true);
  assert.equal(formatted.includes('.'), true);
});

test('formatMoney consistent across currencies', () => {
  const amount = 987654;
  const eur = formatMoney(amount, 'EUR');
  const usd = formatMoney(amount, 'USD');
  const gbp = formatMoney(amount, 'GBP');
  assert.equal(eur, '€9,876.54');
  assert.equal(usd, '$9,876.54');
  assert.equal(gbp, '£9,876.54');
});

test('convert USD is larger than EUR', () => {
  const result = convert(100, 'USD');
  assert.equal(result.value > 100, true);
});

test('convert GBP is smaller than EUR', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.value < 100, true);
});

